window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"ps02F0YXYWc","speaker":"Recep Tayyip Erdoğan","role":"President","country":"Türkiye","region":"Europe","url":"https://www.youtube.com/watch?v=ps02F0YXYWc","date":"20260922","title":"🇹🇷 Türkiye - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":2071,"words":3691,"counts":{"claims":47,"promises":8,"attacks":4},"topics":[{"topic":"Israel-Gaza","share":0.272,"seconds":563},{"topic":"Ceremony","share":0.0837,"seconds":173},{"topic":"Digital divide","share":0.0731,"seconds":151},{"topic":"Climate COP31","share":0.0643,"seconds":133},{"topic":"Oppressed rights","share":0.061,"seconds":126},{"topic":"Global conflicts","share":0.0425,"seconds":88},{"topic":"UNFAO nomination","share":0.0409,"seconds":85},{"topic":"International law","share":0.0402,"seconds":83},{"topic":"Northern Cyprus","share":0.0365,"seconds":76},{"topic":"UN effectiveness","share":0.0347,"seconds":72},{"topic":"Black Sea attacks","share":0.0342,"seconds":71},{"topic":"Africa relations","share":0.0331,"seconds":69},{"topic":"Global cooperation","share":0.0327,"seconds":68},{"topic":"Turic States","share":0.0321,"seconds":67},{"topic":"UN Security Council reform","share":0.0301,"seconds":62},{"topic":"Armenia normalization","share":0.0297,"seconds":62},{"topic":"Syria Iraq Ukraine","share":0.0295,"seconds":61},{"topic":"Food waste","share":0.0295,"seconds":61}],"timeline":[[5,79,"Ceremony"],[85,154,"Israel-Gaza"],[156,246,"Israel-Gaza"],[247,335,"Global conflicts"],[337,399,"Israel-Gaza"],[404,485,"Israel-Gaza"],[486,558,"Israel-Gaza"],[569,641,"UN effectiveness"],[644,709,"Israel-Gaza"],[712,774,"UN Security Council reform"],[776,859,"International law"],[864,932,"Global cooperation"],[933,995,"Digital divide"],[996,1059,"Israel-Gaza"],[1060,1122,"Israel-Gaza"],[1125,1186,"Syria Iraq Ukraine"],[1190,1261,"Black Sea attacks"],[1262,1337,"Northern Cyprus"],[1340,1402,"Armenia normalization"],[1404,1471,"Turic States"],[1472,1541,"Africa relations"],[1542,1609,"Climate COP31"],[1611,1677,"Climate COP31"],[1678,1739,"Food waste"],[1743,1828,"UNFAO nomination"],[1831,1922,"Digital divide"],[1922,1985,"Oppressed rights"],[1986,2049,"Oppressed rights"],[2050,2110,"Ceremony"],[2111,2151,"Ceremony"]],"stances":{"Ceremony":"Recep Tayyip Erdoğan greets the assembly and expresses pleasure at addressing them again.","Israel-Gaza":"Recep Tayyip Erdoğan expresses sadness that the President of Palestine has been unable to attend the UN General Assembly sessions for two consecutive years despite the state's official recognition by most member states.","Global conflicts":"Recep Tayyip Erdoğan states that despite 81 years since the UN Charter's signing, humanity is still waiting for its ideals to be realized due to a surge in recent global violence.","UN effectiveness":"Recep Tayyip Erdoğan states that the United Nations is no longer able to fulfill its mission of maintaining international peace and security due to being weakened.","UN Security Council reform":"Recep Tayyip Erdoğan argues that the current UN Security Council structure is unfair and lacks trust because it allows five countries to dictate the will of over 190 nations, necessitating reform based on the principle that the world is larger than just those five.","International law":"Recep Tayyip Erdoğan argues that international law is currently applied unequally to the strong versus the weak and calls for a change in this mindset.","Global cooperation":"Recep Tayyip Erdoğan argues that international relations must be rebuilt on cooperation and open diplomacy to address income inequality, asserting that mistrust yields no winners.","Digital divide":"Recep Tayyip Erdoğan argues that techno-polarization and digital hegemony harm the UN system and member states, advocating for a human-centered technological approach to prevent new barriers.","Syria Iraq Ukraine":"Recep Tayyip Erdoğan states Turkey's continued support for Syria and Iraq while expressing hope for a resolution to the Russia-Ukraine war that upholds Ukraine's sovereignty.","Black Sea attacks":"Recep Tayyip Erdoğan states that recent attacks on commercial ships in the Black Sea are unacceptable and calls for freedom of navigation in the Strait of Hormuz, while advocating for an Eastern Mediterranean conference to resolve issues based on international law.","Northern Cyprus":"Recep Tayyip Erdoğan calls for international recognition of the Turkish Republic of Northern Cyprus and the establishment of relations with it.","Armenia normalization":"Recep Tayyip Erdoğan states that Turkey is advancing the normalization process with Armenia and supports a lasting peace between Azerbaijan and Armenia.","Turic States":"Recep Tayyip Erdoğan describes the Organization of Turkic States as an exemplary model of regional cooperation and expresses hope for new developments at the upcoming summit.","Africa relations":"Recep Tayyip Erdoğan states that Turkey supports ceasefire efforts in Sudan, security and development in Somalia, stability in Libya, and has elevated relations with ASEAN to a dialogue partnership.","Climate COP31":"Recep Tayyip Erdoğan states that developing countries face difficulties accessing climate funding and announces Turkey will host the COP 31 summit in Antalya.","Food waste":"Recep Tayyip Erdoğan states that food waste is a serious threat comparable to climate change and argues that true justice cannot exist while food is discarded while people starve.","UNFAO nomination":"Recep Tayyip Erdoğan states that Turkey has nominated Dr. Mehmed Mi Akash for the position of director general of the Food and Agriculture Organization and expresses confidence in receiving support for the candidate.","Oppressed rights":"Recep Tayyip Erdoğan asserts that silence and the removal of his voice will not resolve historical injustices or escape moral accountability."},"claims":[{"t":140,"quote":"The state of Palestine is officially recognized by the overwhelming majority of member states here.","topic":"Israel-Gaza","kind":"fact"},{"t":146,"quote":"his excellency Mahmud Abbas, the esteemed president of the state of Palestine, has been unable to attend these sessions for two consecutive years now.","topic":"Israel-Gaza","kind":"fact"},{"t":165,"quote":"although President Abbas is unable to be with us here in person, we will, as we did last year, continue to be the voice of a free and sovereign state of Palestine.","topic":"Israel-Gaza","kind":"fact"},{"t":210,"quote":"when the UN charter was signed on the 26th of June 1945, the member states declared the following with a lot of quote, \"We the peoples of the United determined to save succeeding generations from the scourge of war which twice in our lifetime has brought untold sorrow to mankind and to reaffirm faith in fundamental human rights in the dignity and worth of the human person\"","topic":"Israel-Gaza","kind":"fact"},{"t":303,"quote":"The past 12 months have gone down in history as one of the bloodiest periods of the last 30 years, marked by more than 60 conflicts","topic":"Global conflicts","kind":"number"},{"t":346,"quote":"In Gaza alone over the past 3 years, we have lost 74,000 of our brothers and sisters.","topic":"Israel-Gaza","kind":"number"},{"t":390,"quote":"In Gaza's hospitals, more than 70% of power generators are currently out of service service due to fuel shortages.","topic":"Israel-Gaza","kind":"number"},{"t":418,"quote":"Gaza is not only the world's largest graveyard for children, it is also the place with the highest rate of child amputations in the world.","topic":"Israel-Gaza","kind":"fact"},{"t":448,"quote":"a ceasefire was reached thanks to President Trump's efforts and with contributions of countries including my country Turkey.","topic":"Israel-Gaza","kind":"self_credit"},{"t":459,"quote":"the number of Gazans killed exceeded 1,500.","topic":"Israel-Gaza","kind":"number"},{"t":486,"quote":"In Jerusalem, Muslims and Christians are being denied access to holy sites.","topic":"Israel-Gaza","kind":"fact"},{"t":495,"quote":"There is an attempt to destroy UNRWA which is our collective initiative.","topic":"Israel-Gaza","kind":"fact"},{"t":576,"quote":"The United Nations established um 81 years ago to maintain international peace and security is no longer able to fulfill this mission or more precisely it has been rendered unable to do so.","topic":"UN effectiveness","kind":"fact"},{"t":590,"quote":"The UN continues to be weakened.","topic":"UN effectiveness","kind":"fact"},{"t":697,"quote":"Children in Gaza must be safe. When Palestinian children look up at the sky, they will see kites flying freely, not fighter jets, UAVs, or drones.","topic":"Israel-Gaza","kind":"fact"},{"t":751,"quote":"a system in which the will of more than 190 countries is subject to the whim of just five countries","topic":"UN Security Council reform","kind":"fact"},{"t":816,"quote":"an international system where wrongdoers get away with it and to make it worse where impunity has become the norm. Such an international system, let's face it, is doomed to","topic":"International law","kind":"fact"},{"t":846,"quote":"as Turkey, whenever we have acted upon this principle, as in the case of the Black Sea Grain Corridor, we have achieved results and we have contributed to both regional and to global security.","topic":"International law","kind":"self_credit"},{"t":878,"quote":"History has shown us time and again through bitter experiences that there is no winner in a political approach which is built on mistrust.","topic":"Global cooperation","kind":"fact"},{"t":979,"quote":"With every step we take, we seek a more equitable and more humane international Through the defense alliance we have established recently with Pakistan and Saudi Arabia based on the principle of regional ownership.","topic":"Digital divide","kind":"fact"},{"t":1035,"quote":"we remain committed to following through on the agreement we signed in Sharma Shake one year ago.","topic":"Israel-Gaza","kind":"fact"},{"t":1060,"quote":"Attempts to strangle the state of Palestine will God willing, we shall see those good days when an independent state of Palestine based on the 1967 borders with territorial integrity and with East Jerusalem as its capital will be","topic":"Israel-Gaza","kind":"fact"},{"t":1096,"quote":"after 14 years of oppression, Syria initiated a new path with the December 8","topic":"Israel-Gaza","kind":"fact"},{"t":1140,"quote":"We are working with Iraq on strategic transportation and energy projects um that will enhance the welfare of our Particularly among these projects, important is the development road","topic":"Syria Iraq Ukraine","kind":"fact"},{"t":1192,"quote":"recent attacks against commercial ships in the Black Sea, regardless of who carries them uh who carries them out, are unacceptable.","topic":"Black Sea attacks","kind":"fact"},{"t":1226,"quote":"Our proposal for an Eastern Mediterranean conference will contribute to establishing common ground.","topic":"Black Sea attacks","kind":"self_credit"},{"t":1281,"quote":"Turkey, thanks to its growing defense industry and thanks to its resilient economy, continues to be an island of stability in the middle of conflicts in its vicinity.","topic":"Northern Cyprus","kind":"fact"},{"t":1309,"quote":"The NATO Ankara summit which we successfully hosted in July was a concrete manifestation of our commitment to our common security.","topic":"Northern Cyprus","kind":"fact"},{"t":1340,"quote":"We are shaping our future with the European Union precisely through this strategic vision and we expect the same vision from the European Union as well.","topic":"Armenia normalization","kind":"fact"},{"t":1360,"quote":"Within the Balkans peace platform, we are taking joint steps to deepen our cooperation with them.","topic":"Armenia normalization","kind":"fact"},{"t":1408,"quote":"The organization of Turic states has become an exemplary model of regional cooperation that is growing in strength year by year.","topic":"Turic States","kind":"fact"},{"t":1434,"quote":"The fourth Turkey Africa partnership summit which we will organize in Libya in December symbolizes the institutional partnership we have been building for more than two decades now.","topic":"Turic States","kind":"fact"},{"t":1479,"quote":"We fully support efforts for a ceasefire and for lasting peace in Sudan as well as efforts to strengthen security, development, and institutional capacity in Somalia.","topic":"Africa relations","kind":"fact"},{"t":1501,"quote":"It is imperative that the ongoing reconciliation process is led and owned by Libyans themselves. As Turkey, we continue to support the success of this process.","topic":"Africa relations","kind":"fact"},{"t":1531,"quote":"We regard the elevation of our relations with ASEAN to the level of dialogue partnership as a concrete outcome of this approach.","topic":"Africa relations","kind":"fact"},{"t":1602,"quote":"This November, we'll host the COP 31 summit in Antalya province of Turkey.","topic":"Climate COP31","kind":"fact"},{"t":1662,"quote":"In 2017, my wife, Mrs. Eminard initiated the zero waste movement uh with the slogan the world is our common home and this initiative has now evolved into a global campaign to raise awareness.","topic":"Climate COP31","kind":"fact"},{"t":1711,"quote":"Every year, 5.8 trillion plates or servings of food end up in the garbage bin worldwide.","topic":"Food waste","kind":"number"},{"t":1721,"quote":"meaning that more than two billion tons of food are being We cannot speak of justice in a world where tons of food are thrown into the garbage on one side while hundreds of millions of people collect food from garbage containers on the other.","topic":"Food waste","kind":"fact"},{"t":1743,"quote":"As Turkey, we are ready to make every possible contribution both to preventing waste and to ensuring global food","topic":"UNFAO nomination","kind":"fact"},{"t":1757,"quote":"we have nominated Dr. Mehmed Mi Akash for the position of director general of the food and agriculture organization of the UN","topic":"UNFAO nomination","kind":"fact"},{"t":1831,"quote":"Global gender neutralization policies have also turned into a siege targeting innocent children and targeting the institution of family.","topic":"Digital divide","kind":"fact"},{"t":1866,"quote":"Another threat that undermines social peace is the spread of disinformation on social media.","topic":"Digital divide","kind":"fact"},{"t":1944,"quote":"A late poet said the following quote. They think that if we remain silent, the issue will disappear. But even if we remain silent, history will not.","topic":"Oppressed rights","kind":"fact"},{"t":1963,"quote":"They believe that if we if they get rid of us, the problem will be solved. Yet even if they get rid of us, they'll not be able to escape the pangs of their own conscience.","topic":"Oppressed rights","kind":"fact"},{"t":1986,"quote":"Even if they escape the pangs of history, they will not be able to escape the punishment of God.","topic":"Oppressed rights","kind":"fact"},{"t":2080,"quote":"Turkey has chosen the second path and hopefully we'll follow it with patience.","topic":"Ceremony","kind":"fact"}],"promises":[{"t":170,"quote":"we will, as we did last year, continue to be the voice of a free and sovereign state of Palestine. And from this rostroom, from this podium, we'll continue to make the Palestinian people's fight heard throughout the world.","topic":"Israel-Gaza","kind":"promise"},{"t":1043,"quote":"Now, we must begin the reconstruction of Gaza as soon as possible.","topic":"Israel-Gaza","kind":"promise"},{"t":1048,"quote":"In this regard, I call upon you to exert greater pressure, more pressure on Israel.","topic":"Israel-Gaza","kind":"threat"},{"t":1602,"quote":"This November, we'll host the COP 31 summit in Antalya province of Turkey.","topic":"Climate COP31","kind":"promise"},{"t":1611,"quote":"At the summit, we'll ensure that climate justice is given particular prominence.","topic":"Climate COP31","kind":"promise"},{"t":1618,"quote":"With the partnership we have developed with Australia, we aim to make COP 31 and implementation CP where financial commitments are fulfilled, technology transfer is accelerated and promises are actually translated into um concrete","topic":"Climate COP31","kind":"promise"},{"t":2009,"quote":"God willing, for as long as God grants me life, I shall continue from this podium here to defend the rights of the oppressed, the rights of the agrieved and the voiceless.","topic":"Oppressed rights","kind":"promise"},{"t":2027,"quote":"If necessary, we'll endure hardship. If necessary, we'll pay the price, but we will not remain silent in the face of injustice and will never consent to oppression.","topic":"Oppressed rights","kind":"promise"}],"attacks":[{"t":357,"quote":"We lost them to what we regard as acts of state terror by Israel.","topic":"Israel-Gaza","target":"Israel"},{"t":435,"quote":"Gaza has become the most inhumane and shameful concentration camp of our time.","topic":"Israel-Gaza","target":"Gaza"},{"t":471,"quote":"the Israeli government refuses to stop the","topic":"Israel-Gaza","target":"Israel"},{"t":1805,"quote":"We regard the headscarf bans introduced in schools by certain countries as an attack on women's most fundamental","topic":"UNFAO nomination","target":"Unnamed opponents"}],"greece":[{"t":1204,"quote":"We believe that freedom of navigation in the straight of Hermas must be in the Aian Sea and the eastern Mediterranean region.","refers":["Aegean","Eastern Mediterranean"],"tone":"critical","el":"Ο ομιλητής υποστηρίζει ότι η ελευθερία πλοήγησης στο Αιγαίο και την Ανατολική Μεσόγειο πρέπει να διασφαλιστεί.","en":"The speaker asserts that freedom of navigation must be ensured in the Aegean Sea and the Eastern Mediterranean region."},{"t":1217,"quote":"We wish to see existing issues resolved on the basis of good neighborly relations and accordance with international law. Our proposal for an Eastern Mediterranean conference will contribute to establishing common ground.","refers":["Eastern Mediterranean"],"tone":"conciliatory","el":"Ο ομιλητής εκφράζει την επιθυμία για επίλυση των υπαρχόντων ζητημάτων με βάση τις καλές γειτονικές σχέσεις, το διεθνές δίκαιο και μια διάσκεψη για την Ανατολική Μεσόγειο.","en":"The speaker expresses a desire to resolve existing issues based on good neighborly relations, international law, and proposes an Eastern Mediterranean conference to establish common ground."},{"t":1236,"quote":"On this occasion, I once again will repeat the call I had made numerous times in previous UNGA sessions. The sovereign equality and equal international status of the Turkish criate people must be recognized and the inhumane isolation to which they have been subjected must finally come to an end. I call upon the international community to recognize the Turkish Republic of Northern Cyprus and to establish political, diplomatic and economic relations with them.","refers":["Cyprus"],"tone":"hostile","el":"Ο ομιλητής επαναλαμβάνει την απαίτηση για αναγνώριση της κυριαρχικής ισότητας του Τουρκοκυπριακού λαού και της ΤΔΒΚ από την διεθνή κοινότητα.","en":"The speaker reiterates the demand for the international community to recognize the sovereign equality of the Turkish Cypriot people and the Turkish Republic of Northern Cyprus."}],"said":[{"topic":"Israel-Gaza","said":0.272,"reported":0.16,"articles":8},{"topic":"Ceremony","said":0.0837,"reported":0.02,"articles":1},{"topic":"Digital divide","said":0.0731,"reported":0.0,"articles":0},{"topic":"Climate COP31","said":0.0643,"reported":0.0,"articles":0},{"topic":"Oppressed rights","said":0.061,"reported":0.08,"articles":4},{"topic":"Global conflicts","said":0.0425,"reported":0.06,"articles":3},{"topic":"UNFAO nomination","said":0.0409,"reported":0.0,"articles":0},{"topic":"International law","said":0.0402,"reported":0.2,"articles":10},{"topic":"Northern Cyprus","said":0.0365,"reported":0.28,"articles":14},{"topic":"UN effectiveness","said":0.0347,"reported":0.06,"articles":3},{"topic":"Black Sea attacks","said":0.0342,"reported":0.06,"articles":3},{"topic":"Africa relations","said":0.0331,"reported":0.0,"articles":0},{"topic":"Global cooperation","said":0.0327,"reported":0.0,"articles":0},{"topic":"Turic States","said":0.0321,"reported":0.0,"articles":0},{"topic":"UN Security Council reform","said":0.0301,"reported":0.02,"articles":1},{"topic":"Armenia normalization","said":0.0297,"reported":0.0,"articles":0},{"topic":"Syria Iraq Ukraine","said":0.0295,"reported":0.06,"articles":3},{"topic":"Food waste","said":0.0295,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Proto Thema","date":"2026-09-22","title":"Ερντογάν από τη Νέα Υόρκη: «Πολύτιμος φίλος μου ο Τραμπ, να ξεπεράσουμε τα εμπόδια στην αμυντική συνεργασία»","url":"https://www.protothema.gr/world/article/1882568/erdogan-apo-ti-nea-uorki-polutimos-filos-mou-o-trab-na-xeperasoume-ta-ebodia-stin-amudiki-sunergasia","tone":"favourable"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"Ερντογάν στη ΓΣ του ΟΗΕ: Η Γάζα είναι το πιο απάνθρωπο και επαίσχυντο στρατόπεδο συγκέντρωσης της εποχής μας","url":"https://www.naftemporiki.gr/kosmos/2165231/erntogan-sti-gs-toy-oie-i-gaza-einai-to-pio-apanthropo-kai-epaischynto-stratopedo-sygkentrosis-tis-epochis-mas","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-22","title":"Ερντογάν από ΟΗΕ: «Λύση στα ζητήματα του Αιγαίου με βάση το διεθνές δίκαιο»","url":"https://www.flash.gr/erntogan-apo-oie-lysi-sta-zitimata-toy-aigaioy-me-vasi-to-diethnes-dikaio-1082485","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-22","title":"Ερντογάν στον ΟΗΕ: Επίλυση των ζητημάτων στο Αιγαίο με βάση το διεθνές δίκαιο, ζήτησε αναγνώριση του ψευδοκράτους","url":"https://www.protothema.gr/world/article/1882937/erdogan-ston-oie-epilusi-ton-zitimaton-sto-aigaio-me-vasi-to-diethnes-dikaio-zitise-anagnorisi-tou-pseudokratous","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-22","title":"Ερντογάν στον ΟΗΕ: Ζήτησε διάσκεψη για την Ανατολική Μεσόγειο και αναγνώριση του ψευδοκράτους","url":"https://www.newsbomb.gr/kosmos/story/1765240/erntogan-ston-oie-zitise-diaskepsi-gia-tin-anatoliki-mesogeio-kai-anagnorisi-tou-psevdokratous","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-22","title":"Πρόκληση από τον Ερντογάν: Ζήτησε αναγνώριση του ψευδοκράτους από το βήμα του ΟΗΕ [βίντεο]","url":"https://www.efsyn.gr/kosmos/1472413/proklisi-apo-ton-erntogan-zitise-anagnorisi-toy-pseydokratoys-apo-to-vima-toy-oie-vinteo","tone":"critical"},{"outlet":"Ta Nea","date":"2026-09-22","title":"Νέο κρεσέντο προκλητικότητας Ερντογάν στον ΟΗΕ: Ζήτησε αναγνώριση του ψευδοκράτους και «μοίρασμα» στην Αν. Μεσόγειο","url":"https://www.tanea.gr/2026/09/22/world/neo-kresento-proklitikotitas-erntogan-ston-oie-zitise-anagnorisi-tou-pseydokratous-kai-moirasma-stin-an-mesogeio","tone":"critical"},{"outlet":"In.gr","date":"2026-09-22","title":"Ερντογάν: Επίλυση των ζητημάτων στο Αιγαίο «με βάση το διεθνές δίκαιο» – Ζήτησε αναγνώριση του ψευδοκράτους","url":"https://www.in.gr/2026/09/22/world/erntogan-epilysi-ton-zitimaton-sto-aigaio-me-vasi-to-diethnes-dikaio-zitise-anagnorisi-tou-pseydokratous","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"ΟΗΕ: Οι Ισραηλινοί γύρισαν την πλάτη στον Ερντογάν αποχωρώντας από την αίθουσα (βίντεο)","url":"https://www.naftemporiki.gr/kosmos/2165262/oie-oi-israilinoi-gyrisan-tin-plati-ston-erntogan-apochorontas-apo-tin-aithoysa-vinteo","tone":"neutral"},{"outlet":"To Vima","date":"2026-09-22","title":"Ερντογάν από το βήμα του ΟΗΕ – Εκκλήσεις για Αιγαίο, Κύπρο και ανοικοδόμηση της Γάζας","url":"https://www.tovima.gr/2026/09/22/world/erntogan-apo-to-vima-tou-oie-ekkliseis-gia-aigaio-kypro-kai-anoikodomisi-tis-gazas","tone":"neutral"},{"outlet":"ThePressProject","date":"2026-09-22","title":"Ερντογάν: «Αναγνωρίστε το Παλαιστινιακό κράτος – Ανίκανος ο ΟΗΕ να διατηρήσει την ειρήνη»","url":"https://thepressproject.gr/erntogan-anagnoriste-to-palaistiniako-kratos-anikanos-o-oie-na-diatirisei-tin-eirini","tone":"neutral"},{"outlet":"Documento","date":"2026-09-22","title":"Ερντογάν στον ΟΗΕ: Ζήτησε αναγνώριση του ψευδοκράτους και διάσκεψη για την Ανατολική Μεσόγειο","url":"https://www.documentonews.gr/article/erntogan-ston-oie-zitise-anagnorisi-tou-psevdokratous-kai-diaskepsi-gia-tin-anatoliki-mesogeio","tone":"neutral"},{"outlet":"Avgi","date":"2026-09-22","title":"Ζήτησε αναγνώριση του ψευδοκράτους (βίντεο)","url":"https://www.avgi.gr/diethni/528045_zitise-anagnorisi-toy-pseydokratoys-binteo","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-22","title":"Ο Ερντογάν ζήτησε την αναγνώριση του ψευδοκράτους από το βήμα του ΟΗΕ -Τι είπε για Αιγαίο και διεθνές δίκαιο","url":"https://www.iefimerida.gr/kosmos/o-erntogan-zitise-tin-anagnorisi-toy-pseydokratoys","tone":"critical"},{"outlet":"Proto Thema","date":"2026-09-22","title":"Δείτε βίντεο: Αποχώρησε από την αίθουσα η ισραηλινή αντιπροσωπεία την ώρα που μιλούσε ο Ερντογάν στον ΟΗΕ","url":"https://www.protothema.gr/world/article/1883031/deite-video-apohorise-apo-tin-aithousa-i-israilini-adiprosopeia-tin-ora-pou-milouse-o-erdogan-ston-oie","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-22","title":"ΟΗΕ: Αποχώρησε η ισραηλινή αντιπροσωπεία την ώρα της ομιλίας του Ερντογάν","url":"https://www.flash.gr/apochorise-i-israilini-antiprosopeia-tin-ora-tis-omilias-erntogan-1082513","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-22","title":"Συνομιλία Ερντογάν - Γκουτέρες στη Νέα Υόρκη με Γάζα και Κυπριακό στο «μενού»","url":"https://www.flash.gr/synomilia-erntogan-gkoyteres-sti-nea-yorki-me-gaza-kai-kypriako-sto-menoy-1082516","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"Συνάντηση Ρετζέπ Ταγίπ Ερντογάν με τον γενικό γραμματέα του ΟΗΕ Αντόνιο Γκουτέρες","url":"https://www.naftemporiki.gr/kosmos/2165328/synantisi-retzep-tagip-erntogan-me-ton-geniko-grammatea-toy-oie-antonio-gkoyteres","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-22","title":"Νέο μήνυμα Ερντογάν για το Κυπριακό στη συνάντηση με τον Γκουτέρες","url":"https://www.iefimerida.gr/kosmos/neo-minyma-erntogan-kypriako-synantisi-me-ton-gkoyteres","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-23","title":"Χριστοδουλίδης σε Ερντογάν στον ΟΗΕ: Αν επικαλείστε τον Χάρτη, πρέπει πρώτα να τον εφαρμόζετε, μέγιστη υποκρισία η στάση της Τουρκίας","url":"https://www.protothema.gr/world/article/1883551/hristodoulidis-erdogan-oie-an-epikaleiste-ton-harti-prepei-prota-na-efarmozete-megisti-upokrisia-i-stasi-tis-tourkias","tone":"critical"}],"transcript":[{"t":5,"topic":"Ceremony","text":"The assembly will hear an address by his excellency Rasep Taip Erdogan, President of the Republic of Turkey. I request the protocol to escort his excellency and invite him to address the Mr. President, excellencies, heads of state and government, Mr. Secretary Esteemed delegates, I greet you with my warmest regards on behalf of myself and my nation and I'm deeply pleased to address you once again from this podium."},{"t":85,"topic":"Israel-Gaza","text":"I pray to Almighty God that the 81st session of the UN General Assembly will be a blessing for all of humanity, particularly for the oppressed. I wish to express my sincere appreciation to Miss Barbok for her past term as the president of the general assembly and I extend my best wishes to Mr. Rahman as he assumes the presidency of the general assembly. I would like to extend my congratulations and gratitude to my esteemed friend Mr. Gutes who has served as sec secretary general of the UN for nearly 10 years with impartiality and above all with courage and integrity. First and foremost, I would like to express my sadness over a matter. The state of Palestine is officially recognized by the overwhelming majority of member states here. But his excellency Mahmud Abbas, the esteemed president of the state of Palestine, has been unable to attend these sessions for two consecutive years now."},{"t":156,"topic":"Israel-Gaza","text":"This injustice against our Palestinian brothers and sisters deeply offends the conscience of humanity. Let it be known that although President Abbas is unable to be with us here in person, we will, as we did last year, continue to be the voice of a free and sovereign state of Palestine. And from this rostroom, from this podium, we'll continue to make the Palestinian people's fight heard throughout the world. On this occasion, I once again call upon all countries who have not yet recognized the state of Palestine to reconsider their position. Mr. President, distinguished members, when the UN charter was signed on the 26th of June 1945, the member states declared the following with a lot of quote, \"We the peoples of the United determined to save succeeding generations from the scourge of war which twice in our lifetime has brought untold sorrow to mankind and to reaffirm faith in fundamental human rights in the dignity and worth of the human person"},{"t":247,"topic":"Global conflicts","text":"and to establish conditions under which justice and respect for the obligations arises. ing from treaties can be to live together in peace with with one another as good neighbors and to unite our strength to maintain international peace and security on they declared at the time. But um although it's been 81 years since signing of the treaty, humanity is still eagerly waiting for the day for the strong determination of that time to actually come to life. There's no need to look too far. It's just enough to look at the picture that has unfolded over the last oneear period. Consider this. The past 12 months have gone down in history as one of the bloodiest periods of the last 30 years, marked by more than 60 conflicts and From Gaza to Ukraine and Russia, from Myanmar to Darur, from Iran to Lebanon, people have lost their lives and far more far more number of people have endured indescribable suffering."},{"t":337,"topic":"Israel-Gaza","text":"Hundreds of thousands of people have been forced to leave the lands where they were born and raised. In Gaza alone over the past 3 years, we have lost 74,000 of our brothers and sisters. Most of them women and children, mind you. We lost them to what we regard as acts of state terror by Israel. The people of Gaza are still searching for their loved ones beneath the rubble. They are recovering the bodies of their spouses, their children or parents. Innocent children who have lost their arms and legs in Israeli attacks are trying to return to school. They are trying to hold on to life with prosthetic legs made of wood. In Gaza's hospitals, more than 70% of power generators are currently out of service service due to fuel shortages."},{"t":404,"topic":"Israel-Gaza","text":"as a father and as a grandfather who cherishes his children and grandchildren, I have to say the following from this podium with a heavy Gaza is not only the world's largest graveyard for children, it is also the place with the highest rate of child amputations in the world. Gaza has become the most inhumane and shameful concentration camp of our time. In fact, a ceasefire was reached thanks to President Trump's efforts and with contributions of countries including my country Turkey. But even after the ceasefire, the number of Gazans killed exceeded 1,500. Although the Palestinian resistance movement has agreed to move to the second stage of the peace plan, the Israeli government refuses to stop the Meanwhile, the West Bank is witnessing the most severe period of what we regard as settler violence and terror."},{"t":486,"topic":"Israel-Gaza","text":"In Jerusalem, Muslims and Christians are being denied access to holy sites. There is an attempt to destroy UNRWA which is our collective initiative. Now esteemed friends, today once again I will speak from the heart with complete sincerity and without reservation and I'll state straight some facts plainly. Please don't be offended or upset. I'm sorry but this is not Taip Ardan's personal matter. This is a humanitarian issue. It is a matter of conscience for all of We are faced with a genocidal mindset that can never get enough of killing. We are faced with an extremely serious No one with a sense of humanity, mercy or compassion, no one guided by justice and conscience can possibly remain indifferent to this picture."},{"t":569,"topic":"UN effectiveness","text":"This picture must be a shocking one for all of us and what it tells us is clear. The United Nations established um 81 years ago to maintain international peace and security is no longer able to fulfill this mission or more precisely it has been rendered unable to do so. The UN continues to be weakened. Those in Palestine, in Lebanon, Sudan, and in other crisis zones who have tied their hopes to the UN are deeply But let me remind you that one day everyone will have to seek refuge in the collective conscience of humanity. Today we may feel safe. We may feel prosperous and at peace. Um, today we may live in comfort far away from conflict zones and from crisis areas, but none of us knows what tomorrow will bring or what might happen to us."},{"t":644,"topic":"Israel-Gaza","text":"It is for this reason that I think that this year's um general assembly theme is particularly timely and pertinent because it focuses on restoring trust in the international system. We support the sincere efforts of the secretary general in this regard including efforts around the UN 80 We expect this commitment to reform to continue in the same direction during the next Secretary General's term. Of course, I also want to clearly state the following here. If we truly we are truly committed to restoring confidence in the UN, the steps that must be taken are actually clear. Children in Gaza must be safe. When Palestinian children look up at the sky, they will see kites flying freely, not fighter jets, UAVs, or drones."},{"t":712,"topic":"UN Security Council reform","text":"Children in Lebanon will not wake up in the middle of the night to the sound of The labor of Asian workers will not be exploited by ruthless capitalists. Our African brothers and sisters will look to their future with as much confidence and hope as the citizens of prosperous countries. Now only in this way can trust in the UN be possibly be We must acknowledge that a system in which the will of more than 190 countries is subject to the whim of just five countries is not a fair system and it is not capable of fully inspiring or establishing trust either. The security council must absolutely be reformed in accordance with the principle that the world is bigger than five."},{"t":776,"topic":"International law","text":"Dear friends, while we must keep pace with rapidly advancing technology, we also have the demanding but noble responsibility of building a more equitable international At this point, I want to share with you some basic principles. First and foremost, we are compelled to change the current mindset where international law is applied differently to the strong versus to the weak. Let us not forget that an international system where wrongdoers get away with it and to make it worse where impunity has become the norm. Such an international system, let's face it, is doomed to Secondly, whenever international efforts fall short in resolving crisis, we must harness regional ownership as an effective means of addressing those As Turkey, whenever we have acted upon this principle, as in the case of the Black Sea Grain Corridor, we have achieved results and we have contributed to both regional and to global security."},{"t":864,"topic":"Global cooperation","text":"we must absolutely reestablish an approach that places cooperation and open diplomacy at the core, at the center of relations among states. History has shown us time and again through bitter experiences that there is no winner in a political approach which is built on mistrust. we must jointly build a new paradigm that offers solutions to the increasingly deepening income inequalities around the world. We believe that the path to this lies in joint development, solidarity, and connectivity. Societies connected to one another through roads, trade with energy networks, and joint production will eventually be united in peace and stability as well."},{"t":933,"topic":"Digital divide","text":"And lastly, by promoting a human- centered approach to technology, we must prevent new barriers from being built between those who possess technology and those who do not. It must be understood that techno polarization and digital hijgemony serve neither the interests of the UN centered system nor the interests of those of the states that constitute the United Nations corps. esteemed delegates. Um, Turkey does not confine itself to just articulating these principles. With every step we take, we seek a more equitable and more humane international Through the defense alliance we have established recently with Pakistan and Saudi Arabia based on the principle of regional ownership."},{"t":996,"topic":"Israel-Gaza","text":"We are now both strengthening solidarity among us and aiming to generate solutions to the problems in our region from within the region itself. We are maintaining our efforts with the relevant actors to bring an end to the climate of conflict and to the climate of war that has been ignited in the I strongly underline that any dangerous attempt to spread these conflicts, these um clashes to neighboring regions serves no one's interests. As for Gaza, we remain committed to following through on the agreement we signed in Sharma Shake one year ago. Now, we must begin the reconstruction of Gaza as soon as possible. In this regard, I call upon you to exert greater pressure, more pressure on Israel. Let everyone understand and accept the following."},{"t":1060,"topic":"Israel-Gaza","text":"Attempts to strangle the state of Palestine will God willing, we shall see those good days when an independent state of Palestine based on the 1967 borders with territorial integrity and with East Jerusalem as its capital will be Dear friends, after 14 years of oppression, Syria initiated a new path with the December 8 Under the leadership of President Shara, we are witnessing Syria now moving toward its goal of becoming a safe and peaceful country in spite of all forms of internal and external provocations."},{"t":1125,"topic":"Syria Iraq Ukraine","text":"We'll continue to stand by the brotherly Syrian people on this journey. In Iraq, another neighboring country. We fully support efforts to strengthen state authority and consolidate stability. We are working with Iraq on strategic transportation and energy projects um that will enhance the welfare of our Particularly among these projects, important is the development road As for the Russia Ukraine war, it is our sincere hope that it comes to an end with Ukraine's sovereignty and territorial integrity being upheld. We continue our contacts with the with a view to restoring safety of navigation in the Black Sea, ensuring food security and preventing the war from spreading to a uh wider region."},{"t":1190,"topic":"Black Sea attacks","text":"I would like to particularly emphasize that recent attacks against commercial ships in the Black Sea, regardless of who carries them uh who carries them out, are unacceptable. We believe that freedom of navigation in the straight of Hermas must be in the Aian Sea and the eastern Mediterranean region. We wish to see existing issues resolved on the basis of good neighborly relations and accordance with international law. Our proposal for an Eastern Mediterranean conference will contribute to establishing common ground. On this occasion, I once again will repeat the call I had made numerous times in previous UNGA sessions. The sovereign equality and equal international status of the Turkish criate people must be recognized and the inhumane isolation to which they have been subjected must finally come to an end."},{"t":1262,"topic":"Northern Cyprus","text":"I call upon the international community to recognize the Turkish Republic of Northern Cyprus and to establish political, diplomatic and economic relations with them. esteemed delegates, Turkey, thanks to its growing defense industry and thanks to its resilient economy, continues to be an island of stability in the middle of conflicts in its vicinity. As an integral part of Europe, our country plays a significant role in ensuring the welfare and security of the European continent. The NATO Ankara summit which we successfully hosted in July was a concrete manifestation of our commitment to our common security. A Europe that excludes Turkey from its security architecture cannot, and let me say this clearly, it cannot possibly be stronger or safer."},{"t":1340,"topic":"Armenia normalization","text":"We are shaping our future with the European Union precisely through this strategic vision and we expect the same vision from the European Union as well. The Balkans is a region with which we have strong historical, cultural, and human ties. Within the Balkans peace platform, we are taking joint steps to deepen our cooperation with them. And our position on the South Caucuses is also quite clear. Namely, we hope for the establishment of lasting peace between Azarbaijan and Armenia. We commend and support the commitment to a solution demonstrated uh by President Alv and Prime Minister Pashin. We are also advancing with determination the normalization process between our country and Armenia."},{"t":1404,"topic":"Turic States","text":"Um I would also like to express with pleasure the following. The organization of Turic states has become an exemplary model of regional cooperation that is growing in strength year by year. The 13th leader summit to be held in Ankura on the 30th of October will we hope open new doors and new horizons for the organization. The fourth Turkey Africa partnership summit which we will organize in Libya in December symbolizes the institutional partnership we have been building for more than two decades now. In South Asia, it is important that all disputes, including the Kashmir issue, be addressed through dialogue within the framework of the United Nations Charter and of relevant resolutions. Provided that constructive action is taken, all issues can possibly be resolved."},{"t":1472,"topic":"Africa relations","text":"And the same applies to tensions on the African continent also. We fully support efforts for a ceasefire and for lasting peace in Sudan as well as efforts to strengthen security, development, and institutional capacity in Somalia. Meanwhile, maintaining stability and tranquility in Libya is our priority. It is imperative that the ongoing reconciliation process is led and owned by Libyans themselves. As Turkey, we continue to support the success of this process. also through our Asia ANU initiative, we continue to strengthen our relations with our partners in the Asia-Pacific region. We regard the elevation of our relations with ASEAN to the level of dialogue partnership as a concrete outcome of this approach."},{"t":1542,"topic":"Climate COP31","text":"Likewise, we are developing our relations with the countries of Latin America and the Caribbean on the basis of mutual respect, partnership, and a win-win approach. Distinguished members, we all drive our livelihood and the source of our life from nature. But our world stands on the threshold of serious environmental and climate related threats. Air, water and soil and also many living species are being affected by climate While developing countries and the Pacific region are experiencing the climate crisis to their very core, they unfortunately face serious difficulties in accessing the funding they need. This November, we'll host the COP 31 summit in Antalya province of Turkey."},{"t":1611,"topic":"Climate COP31","text":"At the summit, we'll ensure that climate justice is given particular prominence. With the partnership we have developed with Australia, we aim to make COP 31 and implementation CP where financial commitments are fulfilled, technology transfer is accelerated and promises are actually translated into um concrete So, COP 31 will be made a point of uniting us all. And taking this opportunity, I invite you to the COP 31 leaders summit. In 2017, my wife, Mrs. Eminard initiated the zero waste movement uh with the slogan the world is our common home and this initiative has now evolved into a global campaign to raise awareness."},{"t":1678,"topic":"Food waste","text":"It is a fact that there are for sure many ways to tackle the climate crisis. The zero waste movement is the strongest bridge where all these paths I believe that with your support this bridge will become even stronger. I would also like to draw your attention to the following fact. Another threat as serious as climate change is the spread of a culture of waste fueled by an incredible desire for consumption. Every year, 5.8 trillion plates or servings of food end up in the garbage bin worldwide. meaning that more than two billion tons of food are being We cannot speak of justice in a world where tons of food are thrown into the garbage on one side while hundreds of millions of people collect food from garbage containers on the other."},{"t":1743,"topic":"UNFAO nomination","text":"As Turkey, we are ready to make every possible contribution both to preventing waste and to ensuring global food So with this understanding in mind um we have nominated Dr. Mehmed Mi Akash for the position of director general of the food and agriculture organization of the UN. I'm confident that you will not withhold your support for our candidate. Now, it is also worth noting the following. As our world changes fast, humanity has concurrently begun to face new social threats. which is spreading like a plague in the West, is at the forefront of these In particular, Muslim women and girls have been subjected to greater discrimination in recent years. We regard the headscarf bans introduced in schools by certain countries as an attack on women's most fundamental Rising xenophobia, cultural racism, and anti-semitism are also toxic trends that must be combed with determination."},{"t":1831,"topic":"Digital divide","text":"Global gender neutralization policies have also turned into a siege targeting innocent children and targeting the institution of family. We can break the siege only by protecting the family consisting of women and men. Turkey will continue to take initiatives in protecting families and children in spite of attacks from certain lobby Another threat that undermines social peace is the spread of disinformation on social media. Standing up for the truth has become more important today than ever before. We are also facing the same risk with artificial intelligence AI which is becoming increasingly difficult to It is long overdue now to establish a common international legal framework for It is crucial to accelerate the work which is already being carried out to to draft and bring into force the UN International Convention on Artificial Distinguished delegates, the um realities I've spoken of here today with an"},{"t":1922,"topic":"Oppressed rights","text":"open heart will for sure upset some people, will for sure disrupt their comfort and unmask their lives. I also know well that they will resort to all kinds of perception management operations in an attempt to silence our A late poet said the following quote. They think that if we remain silent, the issue will disappear. But even if we remain silent, history will not. Even if history remains silent, the truth will not. They believe that if we if they get rid of us, the problem will be solved. Yet even if they get rid of us, they'll not be able to escape the pangs of their own conscience. Even if they escape the pangs of their conscience, they will not be able to escape the pangs of history."},{"t":1986,"topic":"Oppressed rights","text":"Even if they escape the pangs of history, they will not be able to escape the punishment of God.\" Estardon. As the president of a great nation guided by its conscience, its history, and its compassion, God willing, for as long as God grants me life, I shall continue from this podium here to defend the rights of the oppressed, the rights of the agrieved and the voiceless. and I'll continue to be their voice to speak on their behalf and to fight for them. If necessary, we'll endure hardship. If necessary, we'll pay the price, but we will not remain silent in the face of injustice and will never consent to oppression. Now, when we look at the course of the world today, we can see that there are two paths before us."},{"t":2050,"topic":"Ceremony","text":"Either we'll deepen uncertainty through fear, through conflict and isolation, or we'll build the future together through justice, solidarity, and common Of course, it is easy to punch darkness. What is difficult is to light a candle that will dispel that darkness. Turkey has chosen the second path and hopefully we'll follow it with patience. May God ease our way and be our guide and helper. I pray. I invite our friends listening to us in this very hall today and from every corner of the world to embrace this shared vision of the I greet you all with the warmest of regards on my own behalf on behalf of my people."},{"t":2111,"topic":"Ceremony","text":"Until we meet again, I salute you all once with respect. I on behalf of the assembly I wish to thank the president of the republic of give them sign. I'm sure. &gt;&gt; Hi. What a pleasure. Yeah."}],"compare":[{"topic":"Israel–Palestine","share":0.2969,"mean":0.0511,"rank":6,"others":76},{"topic":"International Law & Order","share":0.1259,"mean":0.0601,"rank":34,"others":102},{"topic":"UN & its reform","share":0.1154,"mean":0.2052,"rank":137,"others":170},{"topic":"Digital Divide","share":0.0798,"mean":0.0009,"rank":2,"others":3},{"topic":"Climate Change","share":0.0702,"mean":0.0427,"rank":50,"others":77},{"topic":"Human Rights","share":0.0666,"mean":0.0083,"rank":7,"others":24},{"topic":"Cyprus","share":0.0398,"mean":0.0033,"rank":3,"others":2},{"topic":"Black Sea","share":0.0373,"mean":0.0018,"rank":3,"others":2}]};
